SELECT [d0].[Assisted], [d0].[Archived], [d0].[Completed], [u1].[Name], [u1].[UserId], [d0].[Created], [d0].[Date], [d0].[DateType], [d0].[DropId], CASE WHEN EXISTS ( SELECT 1 FROM [AlbumDrops] AS [a] INNER JOIN [Albums] AS [a0] ON [a].[AlbumId] = [a0].[AlbumId] WHERE [d0].[DropId] = [a].[DropId] AND [a0].[UserId] = @__currentUserId_3) THEN CAST(1 AS bit) ELSE CAST(0 AS bit) END, [c].[ContentDropId], [p].[PromptId], [t].[TimelineId], [i1].[ImageDropId], [m1].[MovieDropId], ~CAST([u1].[UserId] ^ @__currentUserId_3 AS bit), [c].[Stuff], [s].[TagId], [s].[Name], [s].[TagDropId], [s].[UserTagId], CASE WHEN [d0].[PromptId] IS NOT NULL THEN CAST(1 AS bit) ELSE CAST(0 AS bit) END, [d0].[PromptId], [p].[Question], CASE WHEN [d0].[TimelineId] IS NOT NULL THEN CAST(1 AS bit) ELSE CAST(0 AS bit) END, [t].[Name], [s0].[Content], [s0].[CommentId], [s0].[Kind], [s0].[UserId], [s0].[c], [s0].[ImageDropId], [s0].[MovieDropId], [s0].[c0], [s0].[c1], [s0].[TimeStamp] FROM ( SELECT [d].[DropId], [d].[Archived], [d].[Assisted], [d].[Completed], [d].[Created], [d].[Date], [d].[DateType], [d].[PromptId], [d].[TimelineId], [d].[UserId] FROM [Drops] AS [d] WHERE EXISTS ( SELECT 1 FROM [NetworkDrops] AS [n] INNER JOIN [UserNetworks] AS [u] ON [n].[UserTagId] = [u].[UserTagId] WHERE [d].[DropId] = [n].[DropId] AND EXISTS ( SELECT 1 FROM [NetworkViewers] AS [n0] WHERE [u].[UserTagId] = [n0].[UserTagId] AND [n0].[UserId] = @__userId_0)) OR [d].[UserId] = @__userId_0 OR EXISTS ( SELECT 1 FROM [UserDrops] AS [u0] WHERE [d].[DropId] = [u0].[DropId] AND [u0].[UserId] = @__userId_0) ORDER BY [d].[Created] DESC OFFSET @__p_1 ROWS FETCH NEXT @__p_2 ROWS ONLY ) AS [d0] INNER JOIN [UserProfiles] AS [u1] ON [d0].[UserId] = [u1].[UserId] LEFT JOIN [ContentDrops] AS [c] ON [d0].[DropId] = [c].[ContentDropId] LEFT JOIN [Prompts] AS [p] ON [d0].[PromptId] = [p].[PromptId] LEFT JOIN [Timelines] AS [t] ON [d0].[TimelineId] = [t].[TimelineId] LEFT JOIN ( SELECT [i].[ImageDropId], [i].[DropId] FROM [ImageDrops] AS [i] WHERE [i].[CommentId] IS NULL ) AS [i1] ON [d0].[DropId] = [i1].[DropId] LEFT JOIN ( SELECT [m].[MovieDropId], [m].[DropId] FROM [MovieDrops] AS [m] WHERE [m].[CommentId] IS NULL ) AS [m1] ON [d0].[DropId] = [m1].[DropId] LEFT JOIN ( SELECT [n1].[UserTagId] AS [TagId], [u2].[Name], [n1].[TagDropId], [u2].[UserTagId], [n1].[DropId] FROM [NetworkDrops] AS [n1] INNER JOIN [UserNetworks] AS [u2] ON [n1].[UserTagId] = [u2].[UserTagId] WHERE [n1].[UserTagId] IN ( SELECT [t0].[value] FROM OPENJSON(@__tagIds_4) WITH ([value] bigint '$') AS [t0] ) ) AS [s] ON [d0].[DropId] = [s].[DropId] OUTER APPLY ( SELECT [c0].[Content], [c0].[CommentId], [c0].[Kind], [u3].[UserId], COALESCE([u3].[Name], [u3].[UserName]) AS [c], [i2].[ImageDropId], [m2].[MovieDropId], CAST([u3].[UserId] ^ @__currentUserId_3 AS bit) AS [c0], CONVERT(varchar(100), [c0].[TimeStamp]) AS [c1], [c0].[TimeStamp] FROM [Comments] AS [c0] INNER JOIN [UserProfiles] AS [u3] ON [c0].[UserId] = [u3].[UserId] LEFT JOIN ( SELECT [i0].[ImageDropId], [i0].[CommentId] FROM [ImageDrops] AS [i0] WHERE [d0].[DropId] = [i0].[DropId] ) AS [i2] ON [c0].[CommentId] = [i2].[CommentId] LEFT JOIN ( SELECT [m0].[MovieDropId], [m0].[CommentId] FROM [MovieDrops] AS [m0] WHERE [d0].[DropId] = [m0].[DropId] ) AS [m2] ON [c0].[CommentId] = [m2].[CommentId] WHERE [d0].[DropId] = [c0].[DropId] ) AS [s0] ORDER BY [d0].[Created] DESC, [d0].[DropId], [u1].[UserId], [c].[ContentDropId], [p].[PromptId], [t].[TimelineId], [i1].[ImageDropId], [m1].[MovieDropId], [s].[TagDropId], [s].[UserTagId], [s0].[CommentId], [s0].[UserId], [s0].[ImageDropId]